import {secureRandom,palette} from '../lib/core.js';
let audio;
export function initAudio(){try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{});}catch{}}
export function tone(frequency=650,duration=.025,delay=0){if(!audio||audio.state!=='running')return;try{const oscillator=audio.createOscillator(),gain=audio.createGain(),at=audio.currentTime+delay;oscillator.connect(gain);gain.connect(audio.destination);oscillator.frequency.value=frequency;gain.gain.setValueAtTime(.045,at);gain.gain.exponentialRampToValueAtTime(.001,at+duration);oscillator.start(at);oscillator.stop(at+duration);}catch{}}
export function celebrate(){const canvas=document.querySelector('#confetti'),ctx=canvas.getContext('2d');const w=innerWidth,h=innerHeight;canvas.width=w;canvas.height=h;const bits=Array.from({length:100},()=>({x:w/2,y:h*.35,vx:(secureRandom()-.5)*15,vy:-secureRandom()*12-3,r:secureRandom()*6+3,c:palette[Math.floor(secureRandom()*palette.length)],a:secureRandom()*6}));const start=performance.now();let previous=start;function frame(now){const elapsed=now-start;const dt=Math.min((now-previous)/16.67,3);previous=now;ctx.clearRect(0,0,w,h);if(elapsed>3000)return;ctx.globalAlpha=Math.min(1,(3000-elapsed)/800);for(const p of bits){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=.18*dt;p.a+=.09*dt;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.a);ctx.fillStyle=p.c;ctx.fillRect(-p.r/2,-p.r/2,p.r,p.r*.55);ctx.restore();}requestAnimationFrame(frame);}requestAnimationFrame(frame);}
